CREATE TABLE #tempMaster(CUSTID INT PRIMARY KEY)
	INSERT INTO #tempMaster(CUSTID)
	SELECT Custid FROM Customer WITH(NOLOCK) WHERE username IN ('MMMRM','MMPRM','MMSD','MMRMB','M822M','M7RM','M7ARM','M7SD','M7RMB','M7ARMB',
	'M7BRMB','M7BRM','M7ZRMB','M7CRM','M926R','M50RM','M39IRMB','M863HK','M789H','M79BR','M79CR','FBR','FBM','MTRE','MTRU','M188SD','S188US','M98RM','M98HK','M98ZR','M98ZH',
	'M79H','M79U','M79V','MQRM','MQARM','MQRMB','MQR','M113H','M90RM','MPHSD','M63H','M63IRMB','M63IHK'
	)
CREATE TABLE #tempAgent(CUSTID INT PRIMARY KEY)
INSERT INTO #tempAgent(CUSTID)
SELECT Custid FROM Customer WITH(NOLOCK) WHERE username IN ('BBM','3KHK','266HK','1188MR','PHRM'	)


INSERT INTO #tempCusts(custid,site)
SELECT c.custid,s.site
FROM dbo.Customer s WITH(NOLOCK)
INNER JOIN custInfo c WITH(NOLOCK) ON c.srecommend=s.custid
WHERE (s.roleid = 4 	
AND s.custid NOT IN (SELECT custid FROM Dep_CustSuper WITH(NOLOCK)) 
AND c.Enabled=1	
AND c.custid>@maxcustid
AND c.roleid BETWEEN 2 AND 4
AND c.srecommend NOT IN (SELECT Custid FROM #tempSuper)
AND c.mrecommend NOT IN (SELECT Custid FROM #tempMaster)
AND c.recommend NOT IN (SELECT Custid FROM #tempAgent)
)

INSERT INTO #tempCustsRacing(custid,site)
SELECT c.custid,s.site
FROM dbo.Customer s WITH(NOLOCK)
INNER JOIN #tempCusts c WITH(NOLOCK) ON s.custid=c.custid
WHERE s.srecommend NOT IN (SELECT Custid FROM #tempSuperRacing)


INSERT INTO #tempCusts(custid,site)
SELECT c.custid,s.site
FROM dbo.Customer s WITH(NOLOCK)
INNER JOIN custInfo c WITH(NOLOCK) ON c.srecommend=s.custid
WHERE (s.roleid = 4 	
AND s.custid NOT IN (SELECT custid FROM Dep_CustSuper WITH(NOLOCK)) 
AND c.Enabled=1	
AND c.custid>@maxcustid
AND c.roleid BETWEEN 2 AND 4
AND c.srecommend NOT IN (SELECT Custid FROM #tempSuper)
AND c.mrecommend NOT IN (SELECT Custid FROM #tempMaster)
AND c.recommend NOT IN (SELECT Custid FROM #tempAgent)
)

-- update casino
UPDATE ci
SET	ci.DisableCasino=0
FROM CustInfo CI WITH (ROWLOCK,UPDLOCK) 
INNER JOIN #tempCusts t ON ci.custid=t.custid
WHERE ci.SyncCasino=1	AND ci.DisableCasino=1	

-- update GD
UPDATE ci
SET	
	ci.[DisableGoldDeluxe]=0
FROM CustInfo CI WITH (ROWLOCK,UPDLOCK) 
INNER JOIN #tempCusts t ON ci.custid=t.custid
WHERE ci.HideGoldDeluxe=0 AND ci.[DisableGoldDeluxe]=1	AND t.site NOT IN ('imbc','789y')
			
--VS
UPDATE ci
SET	ci.DisableVirtualSports=0	
FROM CustInfo CI WITH (ROWLOCK,UPDLOCK) 
INNER JOIN #tempCusts t ON ci.custid=t.custid 
WHERE ci.HideVirtualSports=0 AND ci.DisableVirtualSports=1

UPDATE ci
SET	ci.DisableColossusBet=0
FROM CustInfo CI WITH (ROWLOCK,UPDLOCK) 
INNER JOIN #tempCusts t ON ci.custid=t.custid
WHERE ci.HideColossusBet=0 AND ci.DisableColossusBet=1

UPDATE ci
SET ci.DisableHorseRacing=0,ci.DisableOpenTote=0,ci.Disable151_AU=0,ci.Disable152_AU=0,ci.Disable152_UK=0,ci.Disable153_AU=0	
FROM CustInfo CI WITH (ROWLOCK,UPDLOCK) 
INNER JOIN #tempCustsRacing t ON ci.custid=t.custid

UPDATE ct
SET ct.IsDisabled=0
FROM Custgametype ct WITH (ROWLOCK,UPDLOCK)
INNER JOIN #tempCusts CI WITH(NOLOCK) ON ct.custid=ci.custid
INNER JOIN custInfo c WITH(NOLOCK) ON ci.custid=c.custid
WHERE ct.GameTypeID between 1 and 16 AND c.HideKeno=0 AND ct.IsDisabled=1

DROP TABLE #tempCusts